---@class TakeoutVipOrderStart
---@field Env                            TakeoutVipOrderStart
---@field controller                        Engine.Modules.LuaBehaviour
---@field OverseaManageVipOrderLatticeNode    UnityEngine.RectTransform
---@field GridLayout                        UnityEngine.RectTransform
---@field BtnStart                        UnityEngine.RectTransform
---@field CommonGoodsList                UnityEngine.RectTransform
---@field RewardNode                        UnityEngine.RectTransform
---@field BtnQuick                        UnityEngine.RectTransform
local TakeoutVipOrderStart = Class('TakeoutVipOrderStart')

function TakeoutVipOrderStart:__init()
    self.data = nil
    self.FullTrackTrans = nil
    self.ToTrackTrans = nil
    self.requireNods = nil
    self.onKeyTrans = nil
    self.cb = nil
end

function TakeoutVipOrderStart:__delete()
    self.data = nil
    self.ToTrackTrans = nil
    self.requireNods = nil
    self.onKeyTrans = nil
    self.cb = nil
end

---CanStartTrack
---是否可进行发车逻辑
function TakeoutVipOrderStart:CanStartTrack()
    local isCanStart = 1
    local cooks = self.data.cooks
    if cooks then
        for i, v in pairs(cooks) do
            ---@type CookOrderDojo
            local cookOrderDojo = v
            if checkInt(cookOrderDojo.type) == 1 and (not cookOrderDojo.isSubmit) then
                isCanStart = 0
            end
        end
    end
    return isCanStart
end

function TakeoutVipOrderStart:IsFinalFishTrack()
    local isSubmit = 1
    local cooks = self.data.cooks
    if cooks then
        for i, v in pairs(cooks) do
            ---@type CookOrderDojo
            local cookOrderDojo = v
            if checkInt(cookOrderDojo.type) == 2 and (not cookOrderDojo.isSubmit) then
                isSubmit = 0
            end
        end
    end
    return isSubmit
end

function TakeoutVipOrderStart:Start()
    local canTrack = self:CanStartTrack()
    if canTrack == 1 then
        self:PlayStartTrack()
    end
end

function TakeoutVipOrderStart:PlayStartTrack()
    ----@type UnityEngine.Animation
    local animation = self.controller.transform:GetComponent(typeof(CS.UnityEngine.Animation))
    if animation then
        animation:CrossFade('OverseaManageVipOrderDialog_StartOff')
    end
end

function TakeoutVipOrderStart:OnBtnMakeClick()
    if isNull(self.data) then return end
    local t = {}
    for _, v in pairs(self.data.cooks) do
        if not v.isSubmit then
            local goodsId = checkNumber(v.needId)
            local idType = GoodsUtils.GetIdType(goodsId)
            if idType == Constants.IDType.RestaurantCookingGoods then
                table.insert(t, { goodsId = goodsId, num = checkNumber(v.requireNum) })
            end
        end
    end
    if #t > 0 then
        local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, parameters = { type = MaidCoffeeConstants.CookingType.VipOrder,
                                                                                                     data = t,
                                                                                                     cb = function()
                                                                                                         self:FreshTrackGoods(self.data)
                                                                                                     end } })
    else
        GameUtils.Toast(localize("当前空运订单内没有需要制作的料理"))
    end
end

function TakeoutVipOrderStart:Awake()
    self.requireNods = {}
    self.FullTrackTrans = self.BtnQuick.transform:Find("Complete")
    self.ToTrackTrans = self.BtnQuick.transform:Find("Underway")
    self.onKeyTrans = self.BtnQuick.transform:Find("Onekey")
    KTool.SetActive(self.ToTrackTrans.gameObject, true)
    KTool.SetActive(self.FullTrackTrans.gameObject, false)
    SetButtonAction(self.BtnMake, Bind(self, self.OnBtnMakeClick))
    SetButtonAction(self.BtnQuick, function()
        if KTool.IsActive(self.FullTrackTrans.gameObject) then
            return
        end
        ---一键的逻辑
        local cooks = self.data.cooks
        if cooks then
            local goodsId
            local num = 0
            local settingMgr = SettingMgr:GetInstance()
            local consume = {}
            for i, v in pairs(cooks) do
                ---@type CookOrderDojo
                local cookOrderDojo = v
                if checkInt(cookOrderDojo.type) == 1 and not cookOrderDojo.isSubmit then
                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(cookOrderDojo.needId)
                    local idType = GoodsUtils.GetIdType(goodsVo.id)
                    local path = AutoIds.IdSetting3050
                    if idType == Constants.IDType.GoodsFish then
                        ---如果鱼类
                        path = AutoIds.IdSetting3053
                    end
                    ---@type TableML.TableFile
                    local tableFile = settingMgr:Get(path)
                    ---@type TableML.TableFileRow
                    local row = tableFile:GetByPrimaryKey(cookOrderDojo.needId)
                    local saleId = checkNumber(row:Get("saleId"))
                    if isNull(goodsId) then
                        goodsId = saleId
                    end
                    local saleNum = checkNumber(row:Get("saleNum"))
                    local haveNo = GoodsUtils.GetThingNo(cookOrderDojo.needId)
                    local requireNum = checkNumber(cookOrderDojo.requireNum)
                    if haveNo < requireNum then
                        num = num + (requireNum - haveNo) * saleNum
                    else
                        table.insert(consume, { goodsId = cookOrderDojo.needId, num = -requireNum })
                    end
                end
            end
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if vo then
                ---各消耗充足的情况下
                if num == 0 then
                    GameUtils.Request(Interfaces.MaidCoffeeTakeoutVipOrderSubmit, {}, function(request, response)
                        if checkNumber(response.errCode) == 0 then
                            ---去除消耗
                            local rewards = checkTable(response.data.rewards)
                            GoodsUtils.DrawRewards(consume)
                            if #rewards > 0 then
                                GoodsUtils.DrawRewards(rewards, true)
                                ---去除消耗
                                UIModule.OpenDialog(
                                        {
                                            id = Constants.UITypeIds.UICommonRewardPop,
                                            parameters = { rewards = rewards }
                                        }
                                )
                            end
                            KTool.SetActive(self.ToTrackTrans.gameObject, false)
                            KTool.SetActive(self.onKeyTrans.gameObject, false)
                            KTool.SetActive(self.FullTrackTrans.gameObject, true)
                            self:PlayStartTrack()
                            for i, v in pairs(cooks) do
                                ---@type CookOrderDojo
                                local cookOrderDojo = v
                                if checkInt(cookOrderDojo.type) == 1 then
                                    cookOrderDojo.isSubmit = true
                                end
                            end
                            self:FreshTrackGoods(self.data)
                        end
                    end)
                else
                    GameUtils.SecondConfirm(localize('是否使用_num_个_name_立即提交', { _num_ = tostring(num), _name_ = vo.name }), function()
                        local submitFunc = function()
                            table.insert(consume, { goodsId = goodsId, num = -num })
                            GameUtils.Request(Interfaces.MaidCoffeeTakeoutVipOrderSubmit, {}, function(request, response)
                                if checkNumber(response.errCode) == 0 then
                                    GoodsUtils.DrawRewards(consume)
                                    ---去除消耗
                                    local rewards = checkTable(response.data.rewards)
                                    if #rewards > 0 then
                                        GoodsUtils.DrawRewards(rewards, true)
                                        ---去除消耗
                                        UIModule.OpenDialog(
                                                {
                                                    id = Constants.UITypeIds.UICommonRewardPop,
                                                    parameters = { rewards = rewards }
                                                }
                                        )
                                    end
                                    KTool.SetActive(self.ToTrackTrans.gameObject, false)
                                    KTool.SetActive(self.onKeyTrans.gameObject, false)
                                    KTool.SetActive(self.FullTrackTrans.gameObject, true)
                                    self:PlayStartTrack()
                                    for i, v in pairs(cooks) do
                                        ---@type CookOrderDojo
                                        local cookOrderDojo = v
                                        if checkInt(cookOrderDojo.type) == 1 then
                                            cookOrderDojo.isSubmit = true
                                        end
                                    end
                                    self:FreshTrackGoods(self.data)
                                end
                            end)
                        end
                        local mySaleNo = GoodsUtils.GetThingNo(goodsId)
                        if mySaleNo < num then
                            GoodsUtils.CheckCurrencyConsume({goodsId = goodsId,num = tonumber(num) }, submitFunc)
                            return
                        end
                        submitFunc()
                    end, nil)
                end
            end
        end
    end)
    SetButtonAction(self.BtnStart, function()
        ---发车的逻辑
        if self.cb then
            self.cb()
        end
    end)
end

function TakeoutVipOrderStart:FreshTrackGoods(data)
    if data.cooks then
        ----@type VipOrderDojo
        local fishDojo = nil
        KTool.DestroyGameObjectChildren(self.GridLayout.gameObject, false)
        for i, v in pairs(data.cooks) do
            if checkNumber(v.type) == 1 then
                local go = KTool.Instantiate(self.GridLayout.gameObject, self.OverseaManageVipOrderLatticeNode.gameObject, false)
                KTool.SetActive(go, true)
                ---@type TakeoutVipOrderProductNode
                local env = CfUtils.GetLuaScr(go, TakeoutVipOrderProductNodePath)
                if env then
                    self.requireNods[tostring(v.id)] = env
                    env:FreshUI(v, Bind(self, self.OnProductAction))
                end
            elseif checkNumber(v.type) == 2 then
                fishDojo = v
            end
        end
    end
end

---FreshUI
---@param data VipOrderDojo
function TakeoutVipOrderStart:FreshUI(data, cb)
    self.data = data
    local canTrack = self:CanStartTrack()
    KTool.SetActive(self.ToTrackTrans.gameObject, canTrack == 0)
    KTool.SetActive(self.FullTrackTrans.gameObject, canTrack == 1)
    if canTrack == 1 then
        self:PlayStartTrack()
    else
        ---显示消耗所需的货币
        ---一键的逻辑
        local cooks = self.data.cooks
        if cooks then
            local goodsId
            local num = 0
            local settingMgr = SettingMgr:GetInstance()
            local consume = {}
            for i, v in pairs(cooks) do
                ---@type CookOrderDojo
                local cookOrderDojo = v
                if checkInt(cookOrderDojo.type) == 1 and not cookOrderDojo.isSubmit then
                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(cookOrderDojo.needId)
                    if goodsVo then

                        local idType = GoodsUtils.GetIdType(goodsVo.id)
                        local path = AutoIds.IdSetting3050
                        if idType == Constants.IDType.GoodsFish then
                            ---如果鱼类
                            path = AutoIds.IdSetting3053
                        end
                        ---@type TableML.TableFile
                        local tableFile = settingMgr:Get(path)
                        ---@type TableML.TableFileRow
                        local row = tableFile:GetByPrimaryKey(cookOrderDojo.needId)
                        local saleId = checkNumber(row:Get("saleId"))
                        if isNull(goodsId) then
                            goodsId = saleId
                        end
                        local saleNum = checkNumber(row:Get("saleNum"))
                        local haveNo = GoodsUtils.GetThingNo(cookOrderDojo.needId)
                        local requireNum = checkNumber(cookOrderDojo.requireNum)
                        if haveNo < requireNum then
                            num = num + (requireNum - haveNo) * saleNum
                        else
                            table.insert(consume, { goodsId = cookOrderDojo.needId, num = -requireNum })
                        end
                    end
                end
            end
            ---@type GoodsVo
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if vo then
                local imageIcon = self.ToTrackTrans.transform:Find("Layout/ImgGoodsIcon")
                local TextNumber = self.ToTrackTrans.transform:Find("Layout/TextNumber")
                if imageIcon then
                    KTool.SetActive(imageIcon.gameObject, num > 0)
                end
                if num > 0 then
                    KTool.SetActive(self.onKeyTrans.gameObject, false)
                    CfUtils.FillImage(imageIcon, vo.photoPath)
                    CfUtils.FillText(TextNumber, tostring(num))
                else
                    KTool.SetActive(self.ToTrackTrans.gameObject, false)
                    KTool.SetActive(self.onKeyTrans.gameObject, true)
                end
            end
        end
    end
    if data.rewards then
        ---@type CommonGoodsList
        local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
        local rewards = checkTable(data.rewards)
        rewardEnv:FreshBaseUI(rewards)
    end
    ---数据
    self:FreshTrackGoods(data)
    if cb then
        self.cb = cb
    end
end

---OnProductAction
---@param data CookOrderDojo
function TakeoutVipOrderStart:OnProductAction(data)
    if not data.isSubmit then
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaManageVipOrderTips, data))
    end
end

---OnProductAction
---@param data CookOrderDojo
function TakeoutVipOrderStart:OnProductCatAction(data)
    data.playerOrderId = self.data.id
    UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaManageVipOrderTips, data))
end

function TakeoutVipOrderStart:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TakeoutVipOrderStart